<link rel="preconnect" href="https://fonts.bunny.net">
<link href="https://fonts.bunny.net/css?family=barriecito:400|dm-sans:400,500,600,700,800|manrope:600,700,800" rel="stylesheet">
<link rel="stylesheet" href="https://unpkg.com/aos@2.3.4/dist/aos.css">
<link rel="stylesheet" href="https://cdn-uicons.flaticon.com/uicons-regular-rounded/css/uicons-regular-rounded.css">
<style>
    :root{--ink:#0d0e0c;--muted:#5f6358;--paper:#f2f2ec;--card:#fff;--line:#d9dccf;--brand:#cfe51f;--brand-soft:#e9f4a1;--accent:#a9c936;--black:#070806;--lav:#dec4fb;--sky:#c8eef3;--peach:#ffd98f;--mint:#c8edbd;--rose:#efc3da;--shadow:0 18px 50px rgba(24,29,17,.11);--r:24px}
    *{box-sizing:border-box}html{scroll-behavior:smooth;overflow-x:hidden}body{margin:0;background:var(--paper);color:var(--ink);font-family:'DM Sans',ui-sans-serif,system-ui;overflow-x:hidden}a{color:inherit;text-decoration:none}img,video{max-width:100%}.fi{display:inline-flex;align-items:center;justify-content:center;line-height:1}:focus-visible{outline:3px solid rgba(214,232,43,.7);outline-offset:3px}
    .visitor-nav-wrap{position:sticky;top:0;z-index:30;padding:10px 18px 0}.visitor-nav{width:min(1240px,100%);margin:0 auto;display:grid;grid-template-columns:auto 1fr;align-items:center;gap:18px;border:1px solid rgba(17,17,15,.14);border-radius:22px;background:rgba(250,250,246,.9);box-shadow:var(--shadow);backdrop-filter:blur(18px);padding:10px 12px}.brand{display:inline-flex;align-items:center;gap:0;color:var(--ink);font:400 31px/1 Barriecito,Manrope,sans-serif;letter-spacing:.01em;text-decoration:none;white-space:nowrap}.brand:hover{color:#6f8200}.nav-menu{display:flex;justify-content:flex-end;align-items:center;gap:6px}.nav-menu>a,.nav-dropdown>button{border:0;background:transparent;color:#3f4439;border-radius:14px;padding:11px 12px;font:800 13px 'DM Sans';cursor:pointer}.nav-menu>a:hover,.nav-menu>a.is-active,.nav-dropdown>button:hover,.nav-dropdown>button.is-active{background:var(--black);color:#fff}.nav-join{background:var(--brand)!important;color:#111!important}.nav-login{background:#fff;border:1px solid var(--line)!important}.nav-dropdown{position:relative}.nav-dropdown-panel{position:absolute;right:0;top:calc(100% + 10px);width:260px;display:grid;grid-template-columns:1fr 1fr;gap:7px;padding:12px;border:1px solid var(--line);border-radius:20px;background:#fff;box-shadow:var(--shadow);opacity:0;visibility:hidden;transform:translateY(8px);transition:.22s}.nav-dropdown:hover .nav-dropdown-panel,.nav-dropdown:focus-within .nav-dropdown-panel{opacity:1;visibility:visible;transform:translateY(0)}.nav-dropdown-panel a{border-radius:13px;background:#f5f6ee;padding:10px;font-weight:800;font-size:12px}.nav-dropdown-panel a:hover{background:var(--brand-soft)}.nav-toggle{display:none;border:0;width:42px;height:42px;border-radius:14px;background:var(--black);color:#fff;justify-self:end}.account-trigger{display:flex!important;align-items:center;gap:8px;background:#fff!important;border:1px solid var(--line)!important;color:var(--ink)!important}.account-avatar{width:28px;height:28px;border-radius:10px;background:var(--brand);display:grid;place-items:center;font:900 13px Manrope;color:#111}.account-copy{max-width:120px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.account-panel{grid-template-columns:1fr!important;width:240px}.account-email{display:block;color:var(--muted);font-size:12px;font-weight:800;padding:4px 8px 8px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
    .shell{width:min(1180px,calc(100% - 36px));margin:0 auto}.wide-shell{width:min(1280px,calc(100% - 36px));margin:0 auto}.section{padding:56px 0}.section.compact{padding:34px 0}.crumbs{display:flex;flex-wrap:wrap;gap:8px;margin:34px 0 18px;color:var(--muted);font-size:13px;font-weight:800}.crumbs span:last-child{color:var(--ink)}.kicker,.eyebrow{margin:0 0 10px;color:#7b8d00;font-size:11px;font-weight:900;letter-spacing:.14em;text-transform:uppercase}.section-head{display:flex;justify-content:space-between;align-items:end;gap:22px;margin-bottom:20px}.section-head h2,.section-title{font:800 clamp(28px,3vw,42px)/1 Manrope;margin:0;letter-spacing:-1.2px}.section-head p,.lead,.muted{color:var(--muted);line-height:1.6}.lead{font-size:clamp(16px,1.4vw,19px);max-width:740px}.hero-card{position:relative;overflow:hidden;border:1px solid var(--line);border-radius:34px;background:linear-gradient(135deg,var(--brand-soft),var(--sky));padding:clamp(28px,5vw,58px);box-shadow:var(--shadow);isolation:isolate}.hero-card::before{content:"";position:absolute;right:-90px;top:-120px;width:330px;height:330px;border-radius:50%;background:rgba(255,255,255,.45);animation:floatSoft 8s ease-in-out infinite;z-index:-1}.hero-card.with-media{display:grid;grid-template-columns:minmax(0,1fr) minmax(280px,.45fr);gap:26px;align-items:center}h1{font:800 clamp(44px,6vw,82px)/.94 Manrope;margin:0;letter-spacing:-3px}h2,h3{font-family:Manrope;margin-top:0}.hero-icon,.media-cover,.card-media{overflow:hidden;background:#fff}.hero-icon{border-radius:28px;border:1px solid rgba(17,17,15,.14);aspect-ratio:1/1}.hero-icon img,.media-cover img,.card-media img,.character-photo img{width:100%;height:100%;object-fit:cover;display:block}
    .btn{display:inline-flex;align-items:center;justify-content:center;gap:9px;min-height:48px;border:0;border-radius:14px;background:var(--black);color:#fff;padding:0 18px;font:800 14px 'DM Sans';cursor:pointer;transition:.2s}.btn:hover{transform:translateY(-2px);box-shadow:0 10px 22px rgba(8,9,7,.14)}.btn.alt{background:var(--brand);color:#111}.btn.ghost{background:#fff;color:var(--ink);border:1px solid var(--line)}.tags{display:flex;flex-wrap:wrap;gap:8px;margin-top:18px}.pill{display:inline-flex;align-items:center;gap:7px;width:max-content;border-radius:999px;background:rgba(255,255,255,.78);border:1px solid rgba(17,17,15,.08);padding:8px 11px;font-size:11px;font-weight:900;text-transform:uppercase}.filter-bar{display:grid;grid-template-columns:repeat(4,minmax(150px,1fr)) auto;gap:10px;margin:24px 0;padding:14px;border:1px solid var(--line);border-radius:24px;background:#fff;box-shadow:0 10px 30px rgba(24,29,17,.04)}.field{display:grid;gap:7px}.field label{font-size:11px;font-weight:900;color:var(--muted);text-transform:uppercase;letter-spacing:.08em}.field input,.field select{min-height:48px;border:1px solid var(--line);border-radius:14px;background:#fbfbf8;padding:0 13px;font:700 13px 'DM Sans';color:var(--ink)}
    .grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.bento-grid{display:grid;grid-template-columns:1.25fr .75fr .75fr;gap:16px}.rail-row{display:flex;gap:16px;overflow:auto;padding:4px 4px 18px;scroll-snap-type:x mandatory}.rail-row::-webkit-scrollbar{display:none}.content-card{position:relative;overflow:hidden;border:1px solid var(--line);border-radius:24px;background:#fff;box-shadow:0 10px 28px rgba(24,29,17,.04);transition:.22s;scroll-snap-align:start}.rail-row .content-card{flex:0 0 clamp(260px,27vw,340px)}.content-card:nth-child(6n+1){background:var(--sky)}.content-card:nth-child(6n+2){background:var(--brand-soft)}.content-card:nth-child(6n+3){background:var(--peach)}.content-card:nth-child(6n+4){background:var(--mint)}.content-card:nth-child(6n+5){background:var(--lav)}.content-card:nth-child(6n){background:var(--rose)}.content-card:hover{transform:translateY(-5px);box-shadow:0 18px 40px rgba(24,29,17,.11)}.card-media{height:210px;margin:12px;border-radius:18px}.card-media img{transition:transform .5s ease}.content-card:hover .card-media img,.mini-card:hover img{transform:scale(1.055)}.card-body{padding:6px 18px 20px}.card-body h2,.card-body h3{font:800 20px/1.12 Manrope;margin:14px 0 8px}.meta{display:flex;justify-content:space-between;gap:10px;margin-top:14px;color:#5f6257;font-size:12px;font-weight:800}.feature-card{min-height:100%;display:grid}.feature-card .card-media{height:330px}.mini-card{display:block;border:1px solid var(--line);border-radius:20px;background:#fff;padding:12px;transition:.2s}.mini-card img{width:100%;height:128px;object-fit:cover;border-radius:14px;background:var(--sky);transition:.45s}.mini-card h3{font:800 15px/1.2 Manrope;margin:10px 0 0}.related-row{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin:18px 0 54px}
    .home-hero{padding:34px 0 36px}.home-hero-panel{min-height:620px;display:grid;grid-template-columns:minmax(0,1fr) minmax(360px,.8fr);gap:26px;align-items:center;border-radius:38px;background:linear-gradient(135deg,#11110f,#22251d);color:#fff;padding:clamp(28px,5vw,62px);overflow:hidden;position:relative}.home-hero-panel .lead{color:rgba(255,255,255,.72)}.hero-actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:24px}.hero-collage{display:grid;grid-template-columns:1fr 1fr;gap:14px;transform:rotate(-2deg)}.hero-tile{border:1px solid rgba(255,255,255,.18);border-radius:24px;overflow:hidden;background:#fff;min-height:190px;box-shadow:0 20px 50px rgba(0,0,0,.22);animation:floatSoft 7s ease-in-out infinite}.hero-tile:nth-child(2){margin-top:44px;animation-delay:.8s}.hero-tile:nth-child(3){grid-column:1/3;min-height:170px;animation-delay:1.4s}.hero-tile img{width:100%;height:100%;object-fit:cover;display:block}.category-card{min-height:270px;padding:14px}.category-card .card-media{height:160px}.detail-layout{display:grid;grid-template-columns:minmax(0,1fr) 330px;gap:22px;margin:22px 0 54px}.article-panel,.side-panel,.calendar-card{border:1px solid var(--line);border-radius:28px;background:#fff;padding:clamp(20px,3vw,32px);box-shadow:0 10px 30px rgba(24,29,17,.04)}.media-cover{border-radius:24px;aspect-ratio:16/8.5;margin-bottom:24px}.body-copy{font-size:1.04rem;line-height:1.85;color:#252620}.body-copy :is(p,ul,ol){max-width:820px}.gallery{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:24px 0}.gallery img{width:100%;height:185px;object-fit:cover;border-radius:18px;background:var(--sky)}.timeline{display:grid;gap:12px;margin-top:24px}.timeline-item{position:relative;padding:16px 16px 16px 42px;border-radius:18px;background:var(--brand-soft)}.timeline-item::before{content:"";position:absolute;left:17px;top:21px;width:11px;height:11px;border-radius:50%;background:var(--black)}.character-photo{overflow:hidden;border-radius:999px 999px 28px 28px;background:var(--mint);aspect-ratio:.82/1;border:1px solid var(--line)}
    .calendar-layout{display:grid;grid-template-columns:minmax(0,1fr) 360px;gap:18px;margin:24px 0 60px}.calendar-grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:9px}.cal-head{text-align:center;color:var(--muted);font-size:11px;font-weight:900}.cal-day{min-height:96px;border:1px solid var(--line);border-radius:15px;background:#fbfbf8;padding:9px;font-weight:900}.cal-day.is-empty{opacity:.35}.cal-event{display:block;margin-top:8px;border-radius:9px;background:var(--mint);padding:6px;font-size:10px;line-height:1.2}.map-preview{min-height:150px;border-radius:18px;background:linear-gradient(135deg,var(--sky),var(--lav));display:grid;place-items:center;text-align:center;font-weight:900;padding:16px}.pagination{display:flex;gap:8px;flex-wrap:wrap;margin:20px 0 58px}.pagination a,.pagination span{padding:10px 13px;border-radius:999px;background:#fff;border:1px solid var(--line);font-weight:900}.pagination .active span,.pagination span[aria-current]{background:var(--black);color:#fff}.explore-page{padding-bottom:10px}.explore-results{margin-bottom:0}.visitor-pager{display:flex;align-items:center;justify-content:space-between;gap:16px;margin:26px 0 18px;padding:14px;border:1px solid var(--line);border-radius:24px;background:#fff;box-shadow:0 10px 30px rgba(24,29,17,.04)}.pager-summary{color:var(--muted);font-size:13px;font-weight:800}.pager-actions{display:flex;align-items:center;justify-content:flex-end;gap:7px;flex-wrap:wrap}.pager-btn,.pager-dots{min-width:42px;min-height:42px;display:inline-flex;align-items:center;justify-content:center;border-radius:999px;padding:0 14px;font-weight:900;font-size:13px}.pager-btn{background:#f5f6ee;border:1px solid var(--line);color:var(--ink)}.pager-btn:hover,.pager-btn.is-active{background:var(--black);border-color:var(--black);color:#fff}.pager-btn.is-disabled{opacity:.45;pointer-events:none}.pager-dots{color:var(--muted);padding:0 5px;min-width:auto}
    .auth-wrap{min-height:calc(100vh - 90px);display:grid;grid-template-columns:minmax(0,1fr) minmax(360px,520px);gap:24px;align-items:center;width:min(1160px,calc(100% - 36px));margin:0 auto;padding:42px 0}.auth-visual{min-height:620px;border-radius:34px;padding:38px;background:linear-gradient(135deg,rgba(8,9,7,.94),rgba(8,9,7,.72)),url('/assets/images/hero section/hero-anime.jfif') center/cover;color:#fff;box-shadow:var(--shadow);display:flex;flex-direction:column;justify-content:space-between}.auth-visual p{color:rgba(255,255,255,.72)}.auth-card{border:1px solid var(--line);border-radius:30px;background:rgba(255,255,255,.9);box-shadow:var(--shadow);padding:28px;backdrop-filter:blur(18px)}.auth-card form{display:grid;gap:14px}.auth-note{color:var(--muted);line-height:1.55}.login-error{min-height:20px;color:#9e2f2f;font-weight:800;font-size:13px}.password-field{position:relative;display:block}.password-toggle{position:absolute;right:8px;top:50%;transform:translateY(-50%);width:38px;height:38px;border:0;border-radius:12px;background:var(--brand-soft);cursor:pointer}.password-rules{border:1px solid #e1e8a7;border-radius:15px;background:#fbffe4;padding:11px 13px;color:#4e5c15;font-size:12px}
    .site-footer{margin-top:56px;padding:54px 22px 38px;background:radial-gradient(circle at 14% 0,rgba(214,232,43,.16),transparent 30%),var(--black);color:#fff}.footer-inner{display:grid;grid-template-columns:minmax(0,1fr) minmax(360px,.8fr);gap:34px;width:min(1180px,100%);margin:0 auto}.site-footer .brand{color:#fff}.site-footer p{max-width:650px;color:rgba(255,255,255,.68);line-height:1.6}.footer-groups{display:grid;grid-template-columns:1fr 1fr;gap:18px}.footer-title{margin:0 0 12px!important;color:#fff!important;font-weight:900}.footer-links{display:flex;flex-wrap:wrap;gap:9px}.footer-links a{display:inline-flex;min-height:40px;align-items:center;border:1px solid rgba(255,255,255,.16);border-radius:999px;padding:0 14px;color:rgba(255,255,255,.88);font-weight:800;font-size:13px;transition:.2s}.footer-links a:hover{background:var(--brand);color:#111;transform:translateY(-2px)}
    [data-reveal]{opacity:0;transform:translateY(18px);transition:opacity .6s ease,transform .6s ease}[data-reveal].is-visible{opacity:1;transform:translateY(0)}@keyframes floatSoft{0%,100%{transform:translate3d(0,0,0)}50%{transform:translate3d(12px,16px,0)}}
    @media(max-width:980px){.home-hero-panel,.hero-card.with-media,.detail-layout,.calendar-layout,.auth-wrap,.footer-inner{grid-template-columns:1fr}.grid,.related-row{grid-template-columns:repeat(2,minmax(0,1fr))}.bento-grid{grid-template-columns:1fr 1fr}.filter-bar{grid-template-columns:1fr 1fr}.auth-visual{min-height:360px}.nav-toggle{display:grid;place-items:center}.visitor-nav{grid-template-columns:auto auto}.nav-menu{grid-column:1/-1;display:grid;grid-template-columns:1fr 1fr;max-height:0;overflow:hidden;transition:max-height .28s ease}.nav-menu.open{max-height:620px}.nav-dropdown-panel{position:static;width:auto;opacity:1;visibility:visible;transform:none;box-shadow:none;margin-top:8px}.nav-dropdown{grid-column:1/-1}.nav-dropdown>button{width:100%;text-align:left}.nav-join,.nav-login{justify-content:center}.account-trigger{width:100%;justify-content:center}.account-panel{width:auto}}@media(max-width:620px){.shell,.wide-shell{width:min(100% - 28px,1180px)}h1{font-size:clamp(38px,13vw,58px);letter-spacing:-2px}.grid,.related-row,.bento-grid,.filter-bar,.footer-groups{grid-template-columns:1fr}.home-hero-panel{min-height:auto;border-radius:28px}.hero-collage{grid-template-columns:1fr 1fr}.hero-tile{min-height:125px}.section-head{display:block}.card-media{height:185px}.feature-card .card-media{height:220px}.gallery{grid-template-columns:1fr}.calendar-grid{gap:5px}.cal-day{min-height:70px;font-size:12px}.visitor-nav-wrap{padding:8px 10px 0}.visitor-nav{border-radius:20px}.nav-menu{grid-template-columns:1fr}.auth-wrap{width:calc(100% - 28px);padding-top:24px}.auth-visual{display:none}}
    .media-cover video{width:100%;height:100%;object-fit:cover;display:block}
    @media(prefers-reduced-motion:reduce){*,*::before,*::after{animation-duration:.01ms!important;animation-iteration-count:1!important;scroll-behavior:auto!important;transition-duration:.01ms!important}[data-reveal]{opacity:1;transform:none}}
</style>
